    48→    public static String shoppingCartToJson(ShoppingCart cart) {
    49→        JsonArrayBuilder cartItems = Json.createArrayBuilder();
    50→        cart.getShoppingCartItemList().forEach(item -> {
    51→            cartItems.add(Json.createObjectBuilder()
    52→                .add("productSku",item.getProduct().getItemId())
    53→                .add("quantity",item.getQuantity())
    54→            );
    55→        });
    56→
    57→        int randomNameAndEmailIndex = ThreadLocalRandom.current().nextInt(RANDOM_NAMES.length);
    58→
    59→        JsonObject jsonObject = Json.createObjectBuilder()
    60→            .add("orderValue", Double.valueOf(cart.getCartTotal()))
    61→            .add("customerName",RANDOM_NAMES[randomNameAndEmailIndex])
    62→            .add("customerEmail",RANDOM_EMAILS[randomNameAndEmailIndex])
    63→            .add("retailPrice", cart.getShoppingCartItemList().stream().mapToDouble(i -> i.getQuantity()*i.getPrice()).sum())
    64→            .add("discount", Double.valueOf(cart.getCartItemPromoSavings()))
    65→            .add("shippingFee", Double.valueOf(cart.getShippingTotal()))
    66→            .add("shippingDiscount", Double.valueOf(cart.getShippingPromoSavings()))
    67→            .add("items",cartItems) 
    68→            .build();
    69→        StringWriter w = new StringWriter();
