    84→        order.setDiscount(rootObject.getJsonNumber("discount").doubleValue());
    85→        order.setShippingFee(rootObject.getJsonNumber("shippingFee").doubleValue());
    86→        order.setShippingDiscount(rootObject.getJsonNumber("shippingDiscount").doubleValue());
