   138→		for (String itemId : quantityMap.keySet()) {
   139→			Product p = shoppingCartService.getProduct(itemId);
   140→			ShoppingCartItem newItem = new ShoppingCartItem();
   141→			newItem.setQuantity(quantityMap.get(itemId));
   142→			newItem.setPrice(p.getPrice());
   143→			newItem.setProduct(p);
   144→			result.add(newItem);
   145→		}
